352: static void alloc_tile_list_buffer(AV1Decoder *pbi) {
353:   // TODO(yunqing): for now, copy each tile's decoded YUV data directly to the
354:   // output buffer. This needs to be modified according to the application
355:   // requirement.
356:   AV1_COMMON *const cm = &pbi->common;
357:   const int tile_width_in_pixels = cm->tile_width * MI_SIZE;
358:   const int tile_height_in_pixels = cm->tile_height * MI_SIZE;
359:   const int ssy = cm->seq_params.subsampling_y;
360:   const int ssx = cm->seq_params.subsampling_x;
361:   const int num_planes = av1_num_planes(cm);
362:   const size_t yplane_tile_size = tile_height_in_pixels * tile_width_in_pixels;
363:   const size_t uvplane_tile_size =
364:       (num_planes > 1)
365:           ? (tile_height_in_pixels >> ssy) * (tile_width_in_pixels >> ssx)
366:           : 0;
367:   const size_t tile_size = (cm->seq_params.use_highbitdepth ? 2 : 1) *
368:                            (yplane_tile_size + 2 * uvplane_tile_size);
369:   pbi->tile_list_size = tile_size * (pbi->tile_count_minus_1 + 1);
370:
371:   if (pbi->tile_list_size > pbi->buffer_sz) {
372:     if (pbi->tile_list_output != NULL) aom_free(pbi->tile_list_output);
373:     pbi->tile_list_output = NULL;
374:
375:     pbi->tile_list_output = (uint8_t *)aom_memalign(32, pbi->tile_list_size);
376:     if (pbi->tile_list_output == NULL)
377:       aom_internal_error(&cm->error, AOM_CODEC_MEM_ERROR,
378:                          "Failed to allocate the tile list output buffer");
379:     pbi->buffer_sz = pbi->tile_list_size;
